      let out=note('Vernier calipers · internal jaw contacts','Use the small internal jaws. Outside diameter does not give internal capacity.')+path(`M${left-10} 190 L${left-10} 350 L${right+10} 350 L${right+10} 190`,C.blue,7)+rect(160,120,420,36,'#233f51')+ticks(170,125,390,39,10);
      if(k>=2)out+=path(`M${tipL} 135 L${tipL} 210 L${tipL+15} 210 M${tipR} 135 L${tipR} 210 L${tipR-15} 210`,C.gold,6);
      if(k>=3)out+=dim(left,270,right,270,`Internal d = ${d} mm`);
