    out+=line(xl,190,xl,260)+line(xr,190,xr,260)+path(`M${xl-48} 270 Q${xl} 315 ${xl+48} 270`,C.blue,3)+path(`M${xr-48} 270 Q${xr} 315 ${xr+48} 270`,C.blue,3);
    if(k>=2)out+=rect(xl-25,240,50,30,C.gold,C.gold)+txt(xl,233,moments?`${v.known} g`:`Body ${v.object}`,14,C.gold,'middle');
