  add('p11-b-e05','viscosity',['Tall liquid cylinder','Small steel sphere','Micrometer','Two timing marks','Stopwatch'],[ctrl('radius','Sphere radius',.4,1.2,.05,.7,'mm'),ctrl('viscosity','Chosen liquid viscosity',.8,1.8,.1,1.2,'Pa·s')],[st('Measure and mark','Measure sphere radius and densities; put two timing marks well below the liquid entry.','Set timing region','The sphere needs a settling region before the first timing mark.',42,45),st('Release without pushing','Release the sphere near the cylinder axis, away from the walls.','Release sphere','The initial accelerating region must not be used for the terminal-speed measurement.',44,22),st('Start at mark A','Start timing as the sphere crosses the upper mark; check equal successive segments for equal times.','Start terminal-region timing','Constant segment times support the terminal-velocity assumption.',44,43),st('Stop at mark B','Stop at the lower mark, calculate speed, repeat and check the low-Reynolds-number condition.','Stop at lower mark','Large spheres, wall effects or turbulence invalidate the simple Stokes formula.',44,70)],viscosity,v=>{const r=v.radius/1000,speed=2*r*r*(7800-1260)*G/(9*v.viscosity);return[row('Terminal speed',speed*1000,'mm/s'),row('Travel through 0.10 m',.1/speed,'s'),row('Reynolds number',1260*speed*2*r/v.viscosity),row('Recovered viscosity',v.viscosity,'Pa·s')];}, 'Steel-density spheres (7800 kg/m³) in a selected ideal viscous liquid (1260 kg/m³). Stokes drag, negligible wall/end corrections and established terminal velocity.', 'η = 2r²(ρ_s − ρ_l)g/(9v); Re = 2ρ_lrv/η');

  function thermometer(x,y,T){const h=Math.max(5,Math.min(160,(T-10)*2));return rect(x,y,16,180,'#dce9f3',C.line,8)+rect(x+5,y+174-h,6,h,C.red,C.red,3)+circle(x+8,y+180,15,C.red,C.ink)+txt(x+30,y+70,`${f(T,1)} °C`,17,C.red);}
