  add('p11-b-e06','cooling',['Warm-water vessel','Thermometer','Stopwatch','Room thermometer'],[ctrl('initial','Initial water temperature',45,75,1,65,'°C'),ctrl('ambient','Room temperature',18,30,1,25,'°C'),ctrl('time','Elapsed time',0,20,.5,5,'min')],[st('Read the room temperature','Record the ambient temperature and keep the vessel away from changing drafts.','Read ambient thermometer','Cooling rate depends on temperature excess above the surroundings.',16,18),st('Set the warm sample','Place the safely warmed water in its fixed container and immerse the thermometer without touching the bottom.','Place water and thermometer','Keep the geometry and water mass constant across observations.',34,56),st('Start equal-interval readings','Start timing and read temperature at regular intervals; advance time with the control.','Start cooling clock','The thermometer and cooling curve change together.',35,36),st('Compare local slopes','Record repeated temperature-time pairs and compare slopes at different temperature excesses.','Record cooling reading','Cooling slows as the water approaches room temperature.',73,57)],s=>cooling(s),v=>{const T=v.ambient+(v.initial-v.ambient)*Math.exp(-.06*v.time);return[row('Elapsed time',v.time,'min'),row('Water temperature',T,'°C'),row('Room temperature',v.ambient,'°C'),row('Local cooling-rate magnitude',.06*(T-v.ambient),'°C/min')];}, 'Illustrative Newton cooling with k=0.06 min⁻¹ and fixed ambient conditions; does not model evaporation or radiant transfer separately.', 'T(t) = T_a + (T₀−T_a)e^(−kt)');

